POLICY_SCHEMA='zero.engineering.runtime_adapter_activation_token_preparation_policy.v1';SCHEMA='zero.engineering.runtime_adapter_activation_token_preparation.v1';POLICY_ID='token_preparation_policy_id';ID='token_preparation_id';POLICY_PREFIX='engineering-runtime-adapter-activation-token-preparation-policy-';PREFIX='engineering-runtime-adapter-activation-token-preparation-'
